            if _fn is None:
                runners.append(
                    (_name, (lambda n=_name: ("FAIL", "no check_%s in the harness" % n)))
                )
                continue
            if "http" in _inspect.signature(_fn).parameters:
                runners.append((_name, (lambda f=_fn: f(http))))
            else:
