def _validate(cap_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    """Refuse a partial, out-of-vocabulary or unknown-field record with a 4xx."""
    if not isinstance(payload, dict):
        raise HTTPException(status_code=422, detail="payload must be an object")
    from app import security

    try:
        security.guard_payload(payload)
    except security.PayloadRefused as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    reserved = sorted(k for k in payload if k in RESERVED_PAYLOAD_KEYS)
    if reserved:
        raise HTTPException(status_code=422, detail="reserved field(s): " + ", ".join(reserved))
    reject_invalid_payload(cap_id, payload)
    model = MODELS[cap_id]
    unknown = sorted(k for k in payload if k not in getattr(model, "FIELDS", []))
    if unknown:
        raise HTTPException(status_code=422, detail="unknown field(s): " + ", ".join(unknown))
    # Types are part of the contract. A string field handed an integer is a
    # caller bug, and absorbing it here would put the wrong type in the store
    # where the next reader would have to guess.
    annotations = dict(getattr(model, "__annotations__", {}) or {})
    for name, value in payload.items():
        declared = str(annotations.get(name, "str"))\
            .replace("Optional[", "").replace("]", "").strip()
        if declared == "str" and not isinstance(value, str):
            raise HTTPException(status_code=422,
                                detail=name + " must be a string")
        if declared in ("int", "float") and (isinstance(value, bool) or not isinstance(value, (int, float))):
            raise HTTPException(status_code=422,
                                detail=name + " must be a number")
    return payload


