    from_status: str | None = None,
) -> Dict[str, Any] | None:
    item_id = _as_item_id(item_id)
    conn = connect()
    try:
        if from_status is None:
            cur = conn.execute(
                "UPDATE work_queue SET status = ?, result = ? WHERE id = ?",
                (
                    status,
                    json.dumps(result, sort_keys=True) if result is not None else None,
                    item_id,
                ),
            )
        else:
            cur = conn.execute(
                "UPDATE work_queue SET status = ?, result = ? WHERE id = ? AND status = ?",
                (
                    status,
                    json.dumps(result, sort_keys=True) if result is not None else None,
                    item_id,
                    from_status,
                ),
            )
        conn.commit()
        if cur.rowcount == 0:
            return None
    finally:
        conn.close()
    return get(item_id)


def recall(key: str) -> Dict[str, Any] | None:
    conn = connect()
    try:
        row = conn.execute(
