        return dict(row) if row else None
    finally:
        conn.close()


def remember(key: str, entity: str, record_id: int) -> None:
    conn = connect()
    try:
        conn.execute(
            "INSERT OR REPLACE INTO idempotency (key, entity, record_id) "
            "VALUES (?, ?, ?)",
            (key, entity, record_id),
        )
        conn.commit()
    finally:
        conn.close()


